using System.IO;
using System.Text.Json;
using VisionCore;
using VisionPlugins.Calibration;
string folder=args.Length>0?args[0]:"image-grid-workspace-trace";int filter=args.Length>1?int.Parse(args[1]):1;var native=File.ReadAllLines("analysis/map-calibration/"+folder+"/image-results.jsonl").Select(s=>JsonDocument.Parse(s)).ToArray();var report=new List<object>();bool failed=false;
foreach(var doc in native){var row=doc.RootElement;int board=row.GetProperty("board").GetInt32();foreach(string name in new[]{"source","target"}){var image=new GrayImage(1000,1000,File.ReadAllBytes($"analysis/map-calibration/image-preprocess-trace/raw-{(name=="source"?1:4):D3}.gray"));var lattice=NImageSourceLatticeAdapter.Find(image,filterStatus:filter)!;var found=NImageBoardRecognition.RecognizeLattice(image,board,lattice);var expected=row.GetProperty(name);int exact=0;var differences=new List<object>();if(found is not null)for(int i=0;i<Math.Min(found.Points.Count,expected.GetArrayLength());i++){var p=found.Points[i];var e=expected[i];bool same=p.IndexX==e[2].GetInt32()&&p.IndexY==e[3].GetInt32()&&BitConverter.SingleToInt32Bits((float)p.X)==BitConverter.SingleToInt32Bits(e[0].GetSingle())&&BitConverter.SingleToInt32Bits((float)p.Y)==BitConverter.SingleToInt32Bits(e[1].GetSingle());if(same)exact++;else if(differences.Count<12)differences.Add(new{i,p,expected=e.Clone()});}bool success=found is not null&&found.Points.Count==expected.GetArrayLength()&&exact==found.Points.Count;failed|=!success;report.Add(new{board,name,count=found?.Points.Count,exact,expected=expected.GetArrayLength(),success,differences});Console.WriteLine($"Source recognition board{board} {name}: {exact}/{found?.Points.Count}/{expected.GetArrayLength()}, success={success}");}}
foreach(var d in native)d.Dispose();Directory.CreateDirectory("analysis/map-calibration/source-recognition");File.WriteAllText("analysis/map-calibration/source-recognition/"+(filter==1?"comparison.json":"filter2-comparison.json"),JsonSerializer.Serialize(new{folder,filter,cases=report.Count,failed,report},new JsonSerializerOptions{WriteIndented=true}));return failed||report.Count!=4?1:0;
